+package quota
+
+import (
+	"sync"
+	"time"
+)
+
+// Limiter allows at most Max calls per key within Window.
+type Limiter struct {
+	Max    int
+	Window time.Duration
+	mu     sync.Mutex
+	hits   map[string][]time.Time
+	now    func() time.Time
+}
+
+// NewLimiter returns a limiter that allows max calls per key within window.
+func NewLimiter(max int, window time.Duration) *Limiter {
+	if max < 1 {
+		max = 1
+	}
+	return &Limiter{Max: max, Window: window, hits: map[string][]time.Time{}, now: time.Now}
+}
+
+// Allow reports whether key may make another call now, and records the call when it may.
+func (l *Limiter) Allow(key string) bool{
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	cutoff := l.now().Add(-l.Window)
+	var kept []time.Time
+	for _, t := range l.hits[key] {
+		if t.After(cutoff) {
+			kept = append(kept, t)
+		}
+	}
+	if len(kept) >= l.Max {
+		l.hits[key] = kept
+		return false
+	}
+	l.hits[key] = append(kept, l.now())
+	return true
+}
