+package quota
+
+import (
+	"testing"
+	"time"
+)
+
+func TestAllowStopsAtMax(t *testing.T) {
+	l := NewLimiter(2, time.Minute)
+	if !l.Allow("a") || !l.Allow("a") {
+		t.Fatal("the first two calls must pass")
+	}
+	if l.Allow("a") {
+		t.Fatal("the third call must be refused")
+	}
+}
+
+func TestAllowForgetsOldHits(t *testing.T) {
+	l := NewLimiter(1, time.Minute)
+	start := time.Unix(1000, 0)
+	l.hits["a"] = []time.Time{start}
+	l.now = func() time.Time { return start.Add(2 * time.Minute) }
+	if !l.Allow("a") {
+		t.Fatal("a hit older than the window must not count")
+	}
+}
